INSERT INTO `onboarding_steps` (`step_id`, `step_order`, `step_name`, `description`) VALUES
(9, 0, 'Step 1 - Send an Intent Letter', 'Draft and send the Intent Letter to the candidate.'),
(10, 1, 'Step 2 -   Acceptance of Intent Letter', 'Candidate reviews and accepts the Intent Letter.'),
(11, 2, 'Step 3 -  Employee Email Creation', 'Create and activate the employees official email ID.'),
(12, 3, 'Step 4 - Fingerprint Punch Creation', 'Register the employees fingerprint for attendance tracking.'),
(13, 4, 'Step 5 -  Collect Verification Documentation', 'Collect the following: ID Proof (Self Attested), Passport-size Photo '),
(14, 5, 'Step 6 -  Collect Old Company Documents', 'Request and receive documents from the employee’s previous employer.\r\n'),
(15, 6, 'Step 7 -  Employee Background verification Process', 'About formal company etc'),
(16, 7, 'Step 8 - Assigned Laptop/Asset and maintain records ', 'Assign a laptop or required office equipment to the employee.'),
(17, 8, 'Step 9 -  Appointment Letter Creation', 'Prepare the Appointment Letter. <br>\r\nSend Soft Copy: Email the Appointment Letter to the employee. <br>\r\nProvide Hard Copy: Hand over a printed copy to the employee. <br>\r\nCollect Signatures Copy: Ensure the employee signs the hard copy for acknowledgment. <br>'),
(19, 9, 'Step 10- Completion of Probation Period ', 'Monitor and track the 3-month probation period. <br>\r\nTake a review meeting<br>'),
(20, 10, 'Step 12 - Employee Status Change: Permanent Confirmation', 'Send Email Notification: Notify the employee about their permanent status via email. <br>\r\nProvide Hard Copy: Hand over a printed confirmation letter to the employee. <br>\r\n');
INSERT INTO `tickets` (`TicketID`, `CategoryID`, `Title`, `Description`, `Status`, `Priority`, `EmployeeID`, `CreatedAt`, `UpdatedAt`, `Rating`) VALUES
(23, 9, 'The clock-out time is not displayed.', 'The clock-out time from yesterday was not displayed.', 'Closed', 'Low', 9, '2025-04-29 04:25:59', '2025-04-29 10:41:08', 9),
(26, 9, 'logout', 'i am logged out in the morning around 8:55 am', 'Closed', 'Low', 29, '2025-05-05 04:07:38', '2025-05-16 09:00:27', 10),
(28, 2, 'Correction in last week Attendance', 'Dear Ma\'am,\r\n\r\nPlease mark my Friday(9th May 2025) attendance in HRM. It\'s Showing N/A.\r\nIn time : 9:00am\r\nOut time : 6:30\r\n\r\nThanks & Regards\r\nKanchan', 'Closed', 'Low', 49, '2025-05-12 12:56:49', '2025-05-14 12:40:49', 5),
(30, 8, 'Agttendance', 'When I clicked at 9 o\'clock, a pop-up appeared immediately asking for confirmation. After I clicked \'OK\', my HRM logged out at the same time. ', 'Resolved', 'Low', 17, '2025-05-13 04:33:08', '2025-05-16 09:38:08', NULL),
(33, 9, 'Request for Attendance Correction Due to Mispunch on 16-05-2025', 'Kindly request correction in attendance due to a mispunch on 16-05-2025 at 6:35 PM in the HRM login system.\r\n\r\n', 'Closed', 'Low', 36, '2025-05-19 04:50:33', '2025-06-16 03:57:35', 4),
(35, 2, 'Attendance update', 'I request you to update my 2025-05-16 log out time. I have logout but it\'s showing N/A.\r\nKindly update Time : 6:35PM.\r\nRegards', 'Closed', 'Low', 49, '2025-05-20 07:14:34', '2025-05-20 07:38:49', 8),
(36, 2, 'Forgot to login ', 'Kindly correct the time of today 9:05.\r\nI forgot to login.', 'Closed', 'Low', 49, '2025-05-21 03:46:16', '2025-05-30 07:24:47', 9),
(37, 2, 'Forgot to login ', 'Kindly correct the time of today 9:05.\r\nI forgot to login.', 'Closed', 'Low', 49, '2025-05-21 03:46:22', '2025-05-30 07:25:23', 8),
(38, 8, 'HRM in not punch in', 'Hi Ma\'am,\r\nHRM is not working properly today just because I can not punch in.\r\n\r\nNotification is appearing already log out.\r\n\r\nPrem', 'Resolved', 'Low', 8, '2025-05-21 07:22:33', '2025-05-21 10:46:25', NULL),
(39, 2, 'Out Timing  update', 'Dear Ma\'am, Please mark my (26th May 2025) attendance in HRM. It\'s Showing N/A.  Out time is 6:35pm\r\n\r\n Thanks & Regards Kanchan', 'Closed', 'Low', 49, '2025-05-28 09:21:47', '2025-05-30 07:26:14', 9),
(40, 5, 'Inquiry Regarding Internship Completion and Employment Status', 'Good afternoon Ma\'am,\r\n\r\nI wanted to inquire about my employment status. As mentioned in my offer letter, the internship period is for three months, after which further continuation depends on my performance.\r\nSince the three-month period is coming to an end and I haven’t received any communication regarding the next steps, I would appreciate it if you could kindly update me on the status.\r\n\r\nThank you for your time and support.\r\nBest regards,\r\nAditya', 'Resolved', 'Low', 42, '2025-05-30 07:18:53', '2025-06-03 12:52:14', NULL),
(46, 2, 'Correction Out timing attendance', 'Please Correct my Out timing attendance of 2025-06-18 , 6:35PM.', 'Resolved', 'Low', 49, '2025-06-24 05:41:58', '2025-06-24 07:31:57', NULL),
(52, 2, 'I forgot to sing out ', 'Date 24 June 2025 exit 6: 37 pm', 'Resolved', 'Low', 53, '2025-06-24 05:43:44', '2025-06-24 07:07:01', NULL),
(53, 9, 'HRM Clock-in Issue – 25th July', 'There was a mispunch in HRM on 25th July - when I tried to clock in, it automatically clocked me out. My actual in-time was 8:55 AM and out-time was 6:35 PM.\r\nKindly request you to update the records. ', 'Resolved', 'Low', 36, '2025-06-30 03:38:34', '2025-06-30 07:09:40', NULL),
(55, 1, 'Request for Salary Slip and Increment Letter', 'I would kindly like to request the salary slips for the current month and last month, along with my increment letter.', 'Resolved', 'Low', 9, '2025-07-07 12:54:45', '2025-07-28 06:40:15', NULL),
(56, 2, 'correct out timing ', 'date of 	2025-09-12 - 6:40pm, 2025-09-18 - 6:03pm, & 2025-09-24 - 6:05pm.', 'Resolved', 'Low', 49, '2025-09-30 08:49:41', '2025-09-30 09:30:44', NULL),
(57, 9, '10-11-2025', 'log in time - 9:12\r\nlog out time - 6:15', 'Resolved', 'Low', 50, '2025-11-25 10:33:24', '2025-11-25 10:50:57', NULL),
(58, 9, '24-11-2025', 'login time - 9:9\r\nlogout time - 6:11', 'Resolved', 'Low', 50, '2025-11-25 10:35:40', '2025-11-25 10:50:46', NULL);
